%[text] # Main ROE Propagation Analysis
%[text] Absolute and relative orbital elements dynamics Based on: ANGLES-ONLY TRACKING AND NAVIGATION FOR APPROACH AND RENDEZVOUS IN GEOSYNCHRONOUS ORBITS Reference: Sullivan "Generalized Angles-Only Navigation Architecture for Autonomous Distributed Space Systems."
clc
clear
cls
%%
%[text] ## Configuration
config = initializeConfig();
%%
%[text] ## Load Constants and Data
const = orbitConst();
const.earthVSOP = vsopConst();
const.ELP = readELP();
const.EOP = readEOP();
const.EGM.GEODEG = config.geodeg;
const.EGM = readEGM2008(const.EGM, config.geodeg);

%%
%[text] ## Configuration Functions
function config = initializeConfig()
config.geodeg = 8;
config.anomalyFlag = 1;

config.jdIni = gc2jd(2021, 1, 1, 12, 0, 0);
config.dt = 60 * 5; % seconds
config.tspanOrbits = 10;
config.opts = odeset('RelTol', 1e-8, 'AbsTol', 1e-8);

config.cannonAm = 20 / 3000;

config.figWindowNum = 1;
end
%[text] ## Setup Test Case
%[text] absolute OE at GEO
chief.a0 = 42159; % 半長軸 [km]
chief.e0 = 0.0001;
chief.inc0 = deg2rad(0.001); % inclination, rad
chief.raan0 = deg2rad(60.0); % Right Ascension of Ascending Node [rad]
chief.w0 = deg2rad(0.0);
chief.M0 = deg2rad(300.0);
chief.uM0 = chief.w0 + chief.M0; % mean argument of latitude, rad
chief.nu0 = trueAnomaly(chief.a0, chief.e0, chief.M0);
chief.u0 = chief.w0 + chief.nu0; % true argument of latitude, rad
chief.n = sqrt(const.GE / chief.a0^3); % mean motion
chief.T = 2 * pi / chief.n; % orbital period
chief.oeIni = [chief.a0, chief.e0, chief.inc0, chief.raan0, chief.w0, chief.nu0]; % initial orbital elements of chief
chief.oe.a(1) = chief.a0;
chief.oe.e(1) = chief.e0;
chief.oe.inc(1) = chief.inc0;
chief.oe.raan(1) = chief.raan0;
chief.oe.w(1) = chief.w0;
chief.oe.nu(1) = chief.nu0;
chief.oe.M(1) = chief.M0;
%%
%[text] ## Run Propagation Analysis
results = runPropagationAnalysis(config, chief, const);
%%
%[text] ## Generate Plots
mee.p_ = results.meeData(:,1);
mee.f_ = results.meeData(:,2);
mee.g_ = results.meeData(:,3);
mee.h_ = results.meeData(:,4);
mee.k_ = results.meeData(:,5);
mee.L_ = results.meeData(:,6);

% comparison at COE
tmp = mee2coe(mee);
coeByMEE = [tmp.a, tmp.e, tmp.inc, tmp.raan, tmp.w, tmp.nu];
coeByGVE = results.coeData;
coeByGVE(:,4) = mod(coeByGVE(:,4), 2*pi); % raan
coeByGVE(:,5) = mod(coeByGVE(:,5), 2*pi); % w
coeByGVE(:,6) = mod(coeByGVE(:,6), 2*pi); % nu


% coeByGVE(:,5)
t_ = results.tspan;

figure %[output:1309fc70]
tiledlayout(3,2) %[output:1309fc70]
nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,1), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,1), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('a') %[output:1309fc70]

nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,2), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,2), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('e') %[output:1309fc70]
nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,3), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,3), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('inc') %[output:1309fc70]
nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,4), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,4), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('raan') %[output:1309fc70]
nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,5), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,5), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('w') %[output:1309fc70]
nexttile %[output:1309fc70]
plot(t_./chief.T, coeByMEE(:,6), 'rx', 'LineWidth', 2); %[output:1309fc70]
hold on %[output:1309fc70]
plot(t_./chief.T, coeByGVE(:,6), 'b', 'LineWidth', 2); %[output:1309fc70]
legend('MEE', 'GVE'); %[output:1309fc70]
xlabel('Time, orbits'), ylabel('nu') %[output:1309fc70]
sgtitle('comparison with COE') %[output:1309fc70]

% comparison at MEE
meeByMEE = results.meeData;
meeByMEE(:,6) = mod(meeByMEE(:,6), 2*pi); % L

coe.a = results.coeData(:,1);
coe.e = results.coeData(:,2);
coe.inc = results.coeData(:,3);
coe.raan = results.coeData(:,4);
coe.w = results.coeData(:,5);
coe.nu = results.coeData(:,6);
tmp = coe2mee(coe);
meeByGVE = [tmp.p_, tmp.f_, tmp.g_, tmp.h_, tmp.k_, tmp.L_];

figure %[output:123c2ccc]
tiledlayout(3,2) %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,1), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,1), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('p') %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,2), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,2), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('f') %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,3), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,3), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('g') %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,4), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,4), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('h') %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,5), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,5), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('k') %[output:123c2ccc]
nexttile %[output:123c2ccc]
plot(t_./chief.T, meeByMEE(:,6), 'rx', 'LineWidth', 2); %[output:123c2ccc]
hold on %[output:123c2ccc]
plot(t_./chief.T, meeByGVE(:,6), 'b', 'LineWidth', 2); %[output:123c2ccc]
legend('MEE', 'GVE'); %[output:123c2ccc]
xlabel('Time, orbits'), ylabel('L') %[output:123c2ccc]
sgtitle('comparison with MEE') %[output:123c2ccc]

gFigs(2)
%%
%[text] ## Propagation Analysis
function results = runPropagationAnalysis(config, chief, const)
% Initialize results structure
tspan = 0:config.dt:(chief.T*config.tspanOrbits);
opts = config.opts;

% Setup initial parameters
para = struct();
para.Rini = itrf2gcrf(config.jdIni, const.EOP)';
para.jdIni = config.jdIni;
para.flag = config.anomalyFlag;
%%
%[text] ## modified equinotical orbital elements
tmp = coe2mee(chief.oe);
meeIni = [tmp.p_, tmp.f_, tmp.g_, tmp.h_, tmp.k_, tmp.L_];
[~, xOut] = ode89(@(t,x) eomMEE(t,x, para, const, config), tspan, meeIni, opts);
meeData = xOut;
%%
%[text] ## classical orbital elements
[~, xOut] = ode89(@(t,x) eomGVE(t,x, para, chief, const, config), tspan, chief.oeIni, opts);
coeData = xOut;

results = struct(...
    'meeData', meeData, ...
    'coeData', coeData, ...
    'tspan', tspan);

end

function [Roi, Rbi, RiECEF] = calcDCM(oe, atti, para, const, t_)
% Calculate DCM from inertial to ECEF frame
RecefI = dcm1axis(3, const.WE * t_) * para.Rini;
RiECEF = RecefI';

% Calculate DCM from inertial to RTN frame
Roi = dcmI2RTN(oe.raan, oe.inc, oe.w, oe.nu);

% Calculate DCM from body-fixed to inertial frame
if isempty(atti)
    Rbi = eye(3);
else
    Rbi = q2dcm(4, atti.q);
end
end


function dxdt = eomGVE(t_, x_, para, chief, const, config)
%% Equations of Motion for Gauss Variational Equations with Quaternion Attitude
% Integrates orbital and attitude dynamics with various perturbations

%% Initialize state variables
oe = extractState(x_, para.flag);

%% Calculate orbital parameters and position
oe = calcOrbitalState(oe, const.GE);
rVec = oe.rVec(:);

%% Calculate coordinate transformations
[Roi, ~, RiECEF] = calcDCM(oe, [], para, const, t_);

%% Calculate perturbing accelerations
% Initialize acceleration vector
aRTN = zeros(3, 1);

% Calculate Earth's gravitational acceleration using EGM2008
tmp = egm2008(rVec', const.EGM.GEODEG, const.EGM.Cnm, const.EGM.Snm, const);
aEarth = RiECEF * tmp(:);
aEarth = Roi * aEarth;
aRTN = aRTN + aEarth;

% Calculate third-body perturbations
jd = para.jdIni + s2day(t_); % Calculate Julian day

% Sun's gravitational force
[aSunI, sunI] = sunG(jd, rVec', const, const.earthVSOP);
aRTN = aRTN + Roi * aSunI(:);

% Moon's gravitational force
[aMoon, ~] = moonG(jd, rVec', const, const.ELP);
aRTN = aRTN + Roi * aMoon(:);

% Solar radiation pressure (if applicable)

sunRelI = sunI' - rVec; % 3x1, km
sunDist = norm(sunRelI); % km

% Apply SRP model
aSRP = srpCannon(config.cannonAm, sunRelI', sunDist*10^3, const);
aSRP = aSRP / 10^3; % km/s^2

aRTN = aRTN + aSRP;

%% Integrate orbital dynamics (Gauss Variational Equations)
dOrbitalState = gve(oe, aRTN, para.flag, const.GE);

%% Combine state derivatives
dxdt = dOrbitalState;
end

%% State Extraction Functions
function oe = extractState(x_, anomalyFlag)
% Extract orbital elements
oe = struct();
oe.a = x_(1);
oe.e = x_(2);
oe.inc = x_(3);
oe.raan = x_(4);
oe.w = x_(5);

% Handle anomaly based on flag
if anomalyFlag == 1
    oe.nu = x_(6);
else
    oe.nu = trueAnomaly(oe.a, oe.e, x_(6));
end

oe.raan = mod(oe.raan, 2*pi);
oe.w = mod(oe.w, 2*pi);
oe.nu = mod(oe.nu, 2*pi);

end

function dxdt = eomMEE(t_, x_, para, const, config)
%% Equations of Motion for Gauss Variational Equations with Quaternion Attitude
% Integrates orbital and attitude dynamics with various perturbations

%% Initialize state variables
oe = extractMEE(x_);

%% Calculate orbital parameters and position
oe = mee2coe(oe);
oe = calcOrbitalState(oe, const.GE);
rVec = oe.rVec(:);
% [rVec, ~] = oe2rv([oe.a, oe.e, oe.inc, oe.raan, oe.ome, oe.f], 1, const.GE);
% rVec = rVec(:);

%% Calculate coordinate transformations
[Roi, ~, RiECEF] = calcDCM(oe, [], para, const, t_);

%% Calculate perturbing accelerations
% Initialize acceleration vector
aRTN = zeros(3, 1);

% Calculate Earth's gravitational acceleration using EGM2008
tmp = egm2008(rVec', const.EGM.GEODEG, const.EGM.Cnm, const.EGM.Snm, const);
aEarth = RiECEF * tmp(:);
aEarth = Roi * aEarth;
aRTN = aRTN + aEarth;

% Calculate third-body perturbations
jd = para.jdIni + s2day(t_); % Calculate Julian day

% Sun's gravitational force
[aSunI, sunI] = sunG(jd, rVec', const, const.earthVSOP);
aRTN = aRTN + Roi * aSunI(:);

% Moon's gravitational force
[aMoon, ~] = moonG(jd, rVec', const, const.ELP);
aRTN = aRTN + Roi * aMoon(:);

% Solar radiation pressure (if applicable)
sunRelI = sunI' - rVec; % 3x1, km
sunDist = norm(sunRelI); % km

% Apply SRP model
aSRP = srpCannon(config.cannonAm, sunRelI', sunDist*10^3, const);
aSRP = aSRP / 10^3; % km/s^2

aRTN = aRTN + aSRP;

%% Integrate orbital dynamics (Gauss Variational Equations)
dOrbitalState = mee(oe, aRTN, const.GE);

dxdt = dOrbitalState;
end

%% State Extraction Functions
function oe = extractMEE(x_)
% Extract orbital elements
oe = struct();
oe.p_ = x_(1);
oe.f_ = x_(2);
oe.g_ = x_(3);
oe.h_ = x_(4);
oe.k_ = x_(5);
oe.L_ = x_(6);
end

